from tests_src import T, Q2, TF

T(33, "33-1", "Tallest in the Tent", "Narrative", [
"Beneath the canvas of the village show tent, where the air hung thick with the smell of trampled grass and warm tea, the judge’s pen hovered above her clipboard for what felt like an hour. Outside, a brass band competed with the shrieks of children on the bouncy castle, but Imani could hear nothing except the relentless pounding of her own pulse.",
"Her sunflower stood at the end of the long table, tall and brazen, its enormous face angled towards the light as though it were fully aware of being watched. She had grown it from a seed scarcely larger than her thumbnail, and every morning since April she had watered it, measured it and murmured encouragement, while her little sister, unimpressed, had rolled her eyes and enquired whether it had answered back.",
"Beside it stood Dev’s entry. Dev lived three doors down and had walked to school beside her for as long as either of them could remember. His sunflower was slighter, its stalk bent in a diffident curve, its head drooping a little lower than seemed dignified. When the two of them had pushed their seeds into the soil in spring, they had made a pact: whoever lost would buy the other an ice cream. It had seemed a wonderfully small thing to wager.",
"“Tallest sunflower,” announced the judge, unfolding a tape measure with a flourish, and she held it against Dev’s stalk first, murmuring figures under her breath. Then she moved along to Imani’s, and Imani’s stomach lurched. Concealed beneath the cloth that skirted the pot was the upturned bucket she had balanced it on at seven that morning, to stop the pot from wobbling on the uneven ground. Until this very second, it had not occurred to her what the bucket would do to the measurement.",
"“Two hundred and forty-two centimetres,” read the judge. “Dev’s was two hundred and thirty-eight. We have a winner.”",
"She pinned a red rosette beside the pot and nodded, evidently satisfied. Around her, people applauded. Imani’s mother, near the entrance, was beaming so broadly that her cheeks must have ached. Dev clapped too, a fraction late, and his smile arrived slowly, as if it had been fetched from somewhere a very long way off.",
"Imani felt the silk ribbons of the rosette brush her wrist. It would be so easy, she reasoned. Nobody had lied, and nobody had cheated; the judge had measured precisely what she had been shown. And yet the bucket sat beneath its cloth like a stone in a shoe, a small, hard fact that every step would only make worse. She thought of the ice cream, of the three doors, of years of walking to school, and she understood that the prize was already costing her more than it was worth.",
"“Excuse me,” she heard herself say. Her voice sounded thin, as though it belonged to somebody else. The judge turned, eyebrows raised. Imani drew a breath, took a step towards the table, and reached for the corner of the cloth.",
"Behind her, the brass band launched into a march, bright and oblivious. Nobody seemed to notice that, inside the tent, the applause had died away.",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 2, the sunflower is described as “brazen”. What does this word suggest about it?",opts=["Weak and easily damaged","Bold and unashamed","Small and neat","Dry and faded"],a="B"),
 dict(d="2b",k="short",m=1,q="In paragraph 2, how long had Imani been caring for her sunflower every morning?",a="Since April.",g="Accept: since April / from April. Do not accept “for years”."),
 dict(d="2b",k="find",m=1,q="Find and copy the words from paragraph 2 that show Imani’s sister did not take the sunflower seriously.",a="rolled her eyes",g="Accept “unimpressed” or “rolled her eyes”."),
 dict(d="2d",k="short",m=2,q="Why did Imani’s stomach lurch when the judge reached her sunflower? Use evidence from the text to explain.",a="She suddenly realised the sunflower was standing on a hidden bucket, which would make it seem taller than it really was.",g="1 mark for the hidden bucket / raised pot. 1 mark for the effect: it would add height so the measurement would be unfair (“what the bucket would do to the measurement”)."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each statement.",items=["Dev lived three doors away from Imani.","The judge measured Imani’s sunflower before Dev’s.","The friends had agreed that the loser would buy an ice cream.","The judge noticed the bucket under the cloth."],a=["T","F","T","F"],g=TF),
 dict(d="2g",k="short",m=2,q="Dev’s smile “arrived slowly, as if it had been fetched from somewhere a very long way off”. What does this suggest about how Dev felt, and how does the writer create this impression?",a="He was disappointed but trying to hide it; the idea of the smile being fetched from far away shows it took great effort.",g="1 mark for disappointed / sad / pretending. 1 mark for explaining the effect of “fetched from a long way off” (effort, reluctance, slow to arrive)."),
 dict(d="2g",k="short",m=1,q="In paragraph 7, the bucket is compared to “a stone in a shoe”. What does this comparison suggest about how Imani felt?",a="Uncomfortable and guilty; the problem was small but would keep hurting.",g="Accept: guilty / uneasy / uncomfortable / it would keep bothering her."),
 dict(d="2d",k="short",m=1,q="“Nobody had lied, and nobody had cheated.” Why does Imani tell herself this?",a="She is trying to excuse herself for saying nothing.",g="Accept any answer about justifying or making it easier to stay silent."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["Imani said, “Excuse me.”","The judge measured Dev’s sunflower.","The judge announced the winner.","Imani’s stomach lurched."],a=[4,1,3,2],g=Q2),
 dict(d="2d",k="mc",m=1,q="What does the phrase “as though it belonged to somebody else” suggest about Imani’s voice?",opts=["It was loud and confident.","It sounded unfamiliar because she was so nervous.","It was angry.","It was hoarse from cheering."],a="B"),
 dict(d="2a",k="mc",m=1,q="In paragraph 4, what does the word “flourish” mean?",opts=["A careless mistake","A quiet murmur","A dramatic movement made for show","A sudden pause"],a="C"),
 dict(d="2g",k="short",m=1,q="The band is described as “bright and oblivious” in the last paragraph. What is the writer suggesting about the band, compared with what is happening in the tent?",a="The band is cheerful and unaware of the tension inside the tent.",g="Accept: it does not know / cannot notice what is happening; contrast between cheerful music and a tense moment."),
 dict(d="2e",k="short",m=2,q="What do you think Imani is about to do? Give one piece of evidence from the last two paragraphs.",a="Tell the judge about the bucket and give up the win; she says “Excuse me” and reaches for the cloth.",g="1 mark for a sensible prediction (admit / confess). 1 mark for evidence (“Excuse me”, took a step, reached for the corner of the cloth)."),
 dict(d="2c",k="mc",m=1,q="Which of these best summarises how Imani’s feelings change through the passage?",opts=["Hopeful, then guilty, then determined to be honest","Bored, then delighted, then furious","Frightened, then relieved, then proud","Confident, then careless, then sleepy"],a="A"),
])

T(33, "33-2", "The Scruff on the Chart", "Recount (Historical)", [
"In the summer of 1967, a young research student named Jocelyn Bell was working at Cambridge University on an unusual scientific instrument. It was a radio telescope, yet it bore no resemblance to the gleaming domes that most people imagine: it was a vast field of wooden posts, strung with miles of wire, which Bell and her fellow students had helped to construct by hammering in the posts and stretching out the cable by hand.",
"The telescope did not take photographs. Instead, it detected radio waves arriving from space, and a pen recorded them as a wavering line on a moving roll of paper. Every day the pen produced about thirty metres of chart, and somebody had to examine every centimetre of it. That responsibility fell to Bell, who worked through the endless paper with a ruler, a pencil and a formidable amount of patience.",
"A few weeks into the survey, she noticed something peculiar. Among the jagged lines lay a small, untidy mark, which she later described as “a bit of scruff”. Most observers would have dismissed it, since radio telescopes pick up all manner of interference and scruff was common. Bell, however, remembered having seen the same mark before, in exactly the same place, and she turned back through her earlier charts to confirm it.",
"This was puzzling. Interference from cars and machinery ordinarily followed the human day, but this mark appeared at the same point in the sky each time, keeping to the stars rather than the clock. Bell asked for the signal to be recorded at a much faster speed. When the new chart came back, the scruff had been stretched into a neat row of pulses, each arriving a little more than a second after the last.",
"No natural signal had ever been known to keep time like a clock. For a brief spell, the team wondered, only half seriously, whether they might be receiving a message, and they jokingly labelled the source LGM-1, short for “Little Green Men”. But when Bell discovered a second signal, then a third and a fourth, in different regions of the sky, the theory collapsed. It seemed absurd that several distant civilisations should all be “speaking” in precisely the same rhythm. The pulses had to come from something natural.",
"The sources became known as pulsars. A pulsar is a tiny, rapidly spinning star, left behind when a much larger star has exhausted its fuel and collapsed. As it spins, it emits a beam of radio waves, rather like a lamp turning on a stand, and each time the beam sweeps across the Earth, a telescope registers a pulse.",
"In 1974, a Nobel Prize was awarded for the discovery, but it went to Bell’s supervisor rather than to her. Many scientists thought this unfair, yet Bell responded with remarkable composure. Decades afterwards, when she received a large prize of her own, she donated all of the money to support students who are under-represented in physics.",
"Her story is frequently told to remind young scientists that discoveries do not always announce themselves with a bang. Sometimes they arrive as a smudge on a page, waiting patiently for the person willing to notice.",
], [
 dict(d="2b",k="short",m=1,q="Look at paragraph 1. Give one thing that Jocelyn Bell and her fellow students did to help build the telescope.",a="Hammered in the wooden posts; stretched out the cable/wire.",g="Accept either."),
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what does the word “formidable” suggest about Bell’s patience?",opts=["It was rather small","It was impressively great","It was quickly running out","It was hard to see"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the phrase from paragraph 2 that tells you how much chart the pen produced each day.",a="about thirty metres of chart",g="Accept “thirty metres of chart” / “about thirty metres”."),
 dict(d="2d",k="short",m=2,q="Why did Bell not dismiss the “bit of scruff” as most observers would have done? Use evidence from paragraph 3.",a="She remembered seeing the same mark in the same place before, and she checked her earlier charts to confirm it.",g="1 mark for remembering the mark had appeared before / in the same place. 1 mark for checking the earlier charts and finding it again."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["The scruff was stretched into a row of pulses.","Bell found further signals in other parts of the sky.","Bell noticed a small, untidy mark on the chart.","The team jokingly named the source LGM-1."],a=[2,4,1,3],g=Q2),
 dict(d="2d",k="short",m=2,q="How did Bell work out that the signal was probably not interference from cars or machinery? Explain fully.",a="It kept to the stars rather than the clock: it appeared at the same point in the sky each time, whereas human interference followed the working day.",g="1 mark for the signal appearing at the same point in the sky each time. 1 mark for contrast with the human day / clock."),
 dict(d="2g",k="short",m=2,q="In paragraph 5, the writer puts “speaking” in quotation marks. Why? What effect does this have?",a="The signals are not really speaking; it makes the idea of many civilisations sending messages seem absurd and helps explain why the theory was dropped.",g="1 mark for: not literal speaking. 1 mark for the effect (shows the idea is unlikely / absurd / supports the argument)."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each statement.",items=["The telescope took photographs of stars.","Bell examined the chart paper herself.","LGM-1 stood for “Little Green Men”.","Bell found only one signal."],a=["F","T","T","F"],g=TF),
 dict(d="2d",k="short",m=1,q="Why did the team stop thinking that the signals might be a message?",a="Bell found several signals in different parts of the sky, all with the same rhythm, which made no sense for messages.",g="Accept any answer referring to more than one signal keeping the same rhythm."),
 dict(d="2a",k="mc",m=1,q="In paragraph 7, what does “composure” mean in the phrase “remarkable composure”?",opts=["Calmness under pressure","Loud complaint","Great speed","Deep confusion"],a="A"),
 dict(d="2g",k="short",m=1,q="A pulsar is compared with “a lamp turning on a stand”. What does this help the reader to understand?",a="How a spinning star sends a beam that sweeps past the Earth at regular intervals.",g="Accept: the beam sweeps round like a turning light / the pulses come regularly."),
 dict(d="2d",k="mc",m=1,q="What does the writer suggest about Jocelyn Bell in the final paragraph?",opts=["She was fortunate and nothing more.","She had the patience and attention to notice small things others overlooked.","She wanted to become famous.","She doubted her own results."],a="B"),
 dict(d="2c",k="mc",m=1,q="Which of these best summarises the whole text?",opts=["A telescope was built in a field near Cambridge.","A student’s careful attention to a small mark led to the discovery of pulsars.","Scientists once received a message from space.","Prizes are always shared fairly."],a="B"),
 dict(d="2c",k="short",m=2,q="Give two ways in which the text shows that Bell was a careful and determined scientist.",a="She examined every centimetre of chart; she remembered and checked the odd mark; she asked for a faster recording; she kept searching and found more signals; she gave her prize money to students.",g="1 mark each for two sensible points supported by the text. Max 2."),
])

T(33, "33-3", "The Stumble That Learned to Dance", "Narrative", [
"In Bonwire, the mornings began with the sound of looms, a steady clack and thump that rolled from doorway to doorway like a drum passed along a street. Abena had grown up inside that rhythm and, much as with her own heartbeat, she had long since ceased to be aware of it.",
"Today she noticed everything, because her grandfather had stepped away from his loom and nodded towards the stool. “The final strip,” he said. Twenty-three narrow bands of cloth lay folded over the rail, each no wider than her hand and each patterned in gold, green and red; when the twenty-fourth was complete, they would be stitched edge to edge into a single cloth, made for a ceremony in the next town.",
"Abena sat, and as she pressed the pedals the threads rose and fell while the shuttle skipped between them with a soft whisper. For an hour all went well, until she glanced down at the pattern and her heart sank, for in her eagerness she had woven the zigzag one row too early, and it would now sit crooked against the strip beside it. The flaw was tiny, scarcely larger than a fingernail, but to her it glared like a drop of ink spilled across a clean white page.",
"She looked towards the doorway, where her grandfather was deep in conversation with a neighbour, his back turned. She could unpick the rows in secret, although that would take hours and the cloth was needed by Friday; alternatively, she could say nothing. “Nobody will notice one row,” she muttered, yet she remembered how her grandfather lifted each finished strip to the light and turned it slowly, as though he were reading it.",
"“Every strip has a name,” he had told her once. “The name is in the pattern, but the pattern is in the hands. Hurry, and the cloth remembers.” She had laughed at the time, since it had seemed a peculiar thing to say about cloth.",
"She was still staring at the fault when a shadow fell across the loom, and her grandfather bent close and studied the strip in a prolonged silence, until she could barely breathe.",
"“I am sorry,” she whispered. “I hurried.”",
"“Yes,” he said. “I can see where.” Then, to her astonishment, he smiled. “Do not unpick it. Look.” Taking the shuttle, he demonstrated how the following rows could climb from the stray zigzag, step by step, until the error became the first stair of an entirely new pattern. “In my father’s day we called this one ‘the stumble that learned to dance’. Some of the finest designs began as mistakes. But you must be brave enough to follow them.”",
"By evening the strip was finished, and the crooked little step sat at its centre, not concealed at all but woven into the design as though it had always been intended. On Friday the twenty-four strips were sewn together, and the cloth was carried away, gleaming like a river at sunset.",
"Nobody in the next town would ever discover which strip was Abena’s, but she would know, and so would her grandfather. And when the looms began again the following morning, clacking their old, patient rhythm, Abena found that she was listening.",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 1, the sound of the looms “rolled from doorway to doorway like a drum passed along a street”. What does this suggest about the sound?",opts=["It was sudden and alarming.","It was steady and travelled from house to house.","It was faint and difficult to hear.","It was out of time."],a="B"),
 dict(d="2b",k="short",m=1,q="How many strips had been woven before Abena began the final one?",a="Twenty-three.",g="Accept 23."),
 dict(d="2b",k="find",m=1,q="Find and copy the phrase from paragraph 3 that tells you how small the mistake really was.",a="scarcely larger than a fingernail",g="Accept “scarcely larger than a fingernail” or “tiny”."),
 dict(d="2g",k="short",m=2,q="“To her it glared like a drop of ink spilled across a clean white page.” What does this comparison suggest about how Abena felt about the mistake? Explain.",a="The mistake seemed very obvious and shameful to her, even though it was small; a drop of ink stands out starkly on a clean page.",g="1 mark for the mistake seeming very noticeable / making her feel bad. 1 mark for explaining the link with ink on a clean page (small but stands out)."),
 dict(d="2d",k="short",m=1,q="Why does Abena remember how her grandfather held each strip up to the light?",a="It reminds her that he examines his work closely, so he would probably notice the mistake.",g="Accept any answer showing she realises the fault might be noticed / that care matters."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Abena’s grandfather showed her how to change the pattern.","Abena noticed the zigzag had been woven too early.","Abena’s grandfather asked her to weave the final strip.","The strips were sewn together."],a=[3,2,1,4],g=Q2),
 dict(d="2d",k="short",m=2,q="How does Abena’s grandfather react to the mistake? What does this show about his character? Use evidence.",a="He does not scold her; he smiles and shows her how to turn the mistake into a new pattern. He is kind, patient and wise.",g="1 mark for his reaction (smiles / no scolding / offers a solution). 1 mark for a suitable trait supported by evidence."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each statement.",items=["The cloth was needed by Friday.","Abena’s grandfather was angry when he saw the mistake.","The new design was called “the stumble that learned to dance”.","Everyone in the next town would know which strip was Abena’s."],a=["T","F","T","F"],g=TF),
 dict(d="2a",k="mc",m=1,q="In paragraph 8, what does “stray” mean?",opts=["Wandering from where it should be","Very large","Bright","Beautifully made"],a="A"),
 dict(d="2g",k="short",m=1,q="The finished cloth is described as “gleaming like a river at sunset”. What impression does this create?",a="That the cloth looked beautiful and glowing, so the mistake had not spoiled it.",g="Accept: beautiful / glowing / rich in colour."),
 dict(d="2d",k="mc",m=1,q="What does the final sentence, “Abena found that she was listening”, suggest?",opts=["She was tired and wanted quiet.","She was now paying attention to the rhythm and finding meaning in it.","She was afraid of the looms.","She could not hear anything."],a="B"),
 dict(d="2c",k="mc",m=1,q="What is the main message of the story?",opts=["Never talk to neighbours.","Cloth should be woven as quickly as possible.","Mistakes can lead to something new if you are brave and patient.","Old designs are better than new ones."],a="C"),
 dict(d="2d",k="short",m=1,q="Give one reason why Abena at first thought about saying nothing about the mistake.",a="She thought nobody would notice one row, and unpicking would take hours.",g="Accept either reason."),
 dict(d="2e",k="short",m=1,q="What do you think Abena will be more careful about in future weaving? Give a reason from the text.",a="Not to hurry, because her grandfather said “Hurry, and the cloth remembers” and the mistake came from hurrying.",g="Accept any sensible answer linked to hurrying."),
])

T(33, "33-4", "Rivers of Ice", "Explanation", [
"Mountain valleys come in two distinct shapes. Those cut by rivers are narrow and steep-sided, with a cross-section like the letter V. Others, however, are broad and flat-bottomed, with towering walls that rise almost vertically on either side, forming a shape closer to a U. Geologists have long known that the U-shaped valleys were not made by water at all. They were carved by glaciers.",
"A glacier begins high in the mountains, in places where more snow falls in winter than melts in summer. Year after year, fresh snow buries the older layers, and the enormous weight squeezes the lower snow until it is compressed into dense, solid ice. Eventually the mass becomes so heavy that it starts to creep downhill under its own weight. Although a glacier looks motionless, it may travel anything from a few centimetres to several metres in a single day.",
"As the ice advances, it shapes the landscape in two main ways. The first is plucking. Meltwater seeps into cracks in the bedrock and freezes, gripping fragments of stone. When the glacier moves on, it drags these rocks away, rather as a tooth might be pulled from a jaw. The second is abrasion. Stones frozen into the base and sides of the glacier scrape against the rock beneath like sandpaper, grinding it smooth and leaving long scratches, known as striations, which point in the direction the ice was travelling.",
"A river winds around obstacles, cutting mainly downwards, which is why river valleys are narrow. A glacier, by contrast, is a single vast slab that cannot bend easily. It ploughs straight through, scouring the floor and the sides equally, and so it widens and deepens the valley into a smooth trough. When the ice finally melts, that trough is left behind.",
"The retreating ice leaves other clues. High on the mountainsides, the source of a glacier often carves a rounded, armchair-shaped hollow called a cirque, and where two neighbouring cirques cut back towards each other, only a thin, jagged ridge remains between them. Smaller glaciers that fed into the main one were less powerful, so their valleys were not cut as deeply. When the ice vanished, these side valleys were left hanging high above the main trough, and streams now tumble from them as waterfalls.",
"Glaciers also act as conveyor belts. The rubble they collect is carried along, then dumped when the ice melts, forming ridges and mounds of mixed clay, sand and boulders called moraines. Some huge boulders, known as erratics, are deposited far from the rock they came from, and geologists can sometimes trace them back to their origin.",
"Much of Britain was once covered by thick ice, and its mountain landscapes still bear the signs. Anyone who walks into a broad, steep-walled valley with a waterfall spilling from a ledge high above is, in effect, standing inside the footprint of a vanished river of ice.",
], [
 dict(d="2b",k="short",m=1,q="In paragraph 1, what shape is a valley cut by a river?",a="A V shape (narrow and steep-sided).",g="Accept: V-shaped / narrow with steep sides."),
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what does the word “compressed” mean?",opts=["Melted slowly","Pressed tightly together","Carried away","Divided into layers"],a="B"),
 dict(d="2c",k="order",m=1,q="Number the stages from 1 to 4 to show how a glacier forms and starts to move.",items=["The ice becomes so heavy that it creeps downhill.","Snow falls in winter and does not all melt in summer.","New snow buries the older layers.","The lower snow is squeezed into solid ice."],a=[4,1,2,3],g=Q2),
 dict(d="2b",k="find",m=1,q="Find and copy the word from paragraph 3 that means the scraping of rock by stones held in the ice.",a="abrasion",g="Accept “abrasion” only."),
 dict(d="2d",k="short",m=2,q="Explain how plucking removes rock from the ground. Use paragraph 3.",a="Meltwater seeps into cracks in the rock and freezes, gripping fragments of stone; when the glacier moves on it drags the stones away.",g="1 mark for water freezing in cracks and gripping stone. 1 mark for the moving glacier dragging the rocks away."),
 dict(d="2d",k="short",m=2,q="Why are glacial valleys wider than river valleys? Use paragraph 4 to explain.",a="A river cuts mainly downwards and winds around obstacles, but a glacier is a huge slab that cannot bend easily and scours the floor and the sides equally.",g="1 mark for river cutting mainly downwards / winding. 1 mark for glacier scouring floor and sides / being a huge slab that ploughs straight through."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each statement.",items=["Glaciers begin in places where more snow falls than melts.","Striations are scratches that show the direction the ice moved.","Glaciers move too fast to be measured.","Hanging valleys were cut by the largest glaciers."],a=["T","T","F","F"],g=TF),
 dict(d="2g",k="short",m=1,q="In paragraph 3, the writer says plucking is “rather as a tooth might be pulled from a jaw”. What does this comparison help the reader to picture?",a="The glacier pulling pieces of rock out of the ground with force.",g="Accept: rock being pulled out / gripped and dragged away."),
 dict(d="2a",k="mc",m=1,q="In paragraph 5, what does “retreating” suggest about the ice?",opts=["It is growing larger","It is pulling back","It is moving faster","It is freezing"],a="B"),
 dict(d="2d",k="short",m=1,q="Why were the side valleys “left hanging” high above the main valley?",a="The smaller glaciers were less powerful, so they cut their valleys less deeply than the main glacier.",g="Accept any answer about smaller glaciers cutting less deeply."),
 dict(d="2g",k="short",m=1,q="In paragraph 6, the writer calls glaciers “conveyor belts”. Why is this a suitable comparison?",a="Like a conveyor belt, a glacier carries material along and then drops it in a new place.",g="Accept: it carries things from one place to another."),
 dict(d="2c",k="mc",m=1,q="What is the main purpose of the final paragraph?",opts=["To describe how moraines are made","To show that the features described can still be seen in Britain today","To explain how erratics travel","To compare river valleys with glacial valleys"],a="B"),
 dict(d="2c",k="mc",m=1,q="Which of these best summarises the text?",opts=["Glaciers are made of snow and move very slowly.","Rivers and glaciers carve the land in exactly the same way.","Moving ice shapes mountain landscapes and leaves lasting features behind when it melts.","Erratics are the most important glacial features."],a="C"),
 dict(d="2e",k="short",m=1,q="A hiker finds a huge boulder that is made of a different rock from everything around it. Using the text, what might explain how it got there?",a="It could be an erratic, carried by a glacier and dropped when the ice melted.",g="Accept any answer that mentions a glacier / ice carrying and dropping it."),
])

T(33, "33-5", "Miles of Stone", "Recount (Historical)", [
"We began at Housesteads Roman Fort at nine o’clock, in a fine drizzle that could not decide whether it was rain or mist. My brother Kwesi had spent the entire car journey complaining that a wall was only a wall, while I had spent it reading aloud from the guidebook. Hadrian’s Wall, I had learned, stretches for about seventy-three miles across the north of England, from near Newcastle in the east to the shores of the Solway Firth in the west, and its construction began in AD 122 on the orders of the Emperor Hadrian.",
"“Seventy-three miles,” Kwesi had muttered. “By hand?”",
"“By soldiers,” I had replied. It was not much of an answer, but we were about to discover exactly how much it was worth.",
"Beyond the fort, the path climbed a grassy ridge, and there, quite suddenly, the wall was in front of us. It was not as tall as I had imagined; in places it rose no higher than my waist, and its grey stones were freckled with orange lichen. Yet it went on and on, rising and falling with the crags like the spine of some enormous sleeping animal, until the mist swallowed it. To the north, the ground fell away in a sheer cliff, and I could see why the builders had chosen this line, since any enemy would have had to climb the whole way in full view.",
"Roughly every mile, we passed the remains of a small square building set into the wall, with a gateway through its middle. These were milecastles, where soldiers once stood guard. The guidebook explained that our word “mile” derives from the Latin for a thousand paces, because Roman soldiers measured distance by counting their steps. When I read this out, Kwesi pretended not to be listening, although I noticed that he had begun to count his own.",
"By late morning the wind had scoured the mist away, and the whole country opened out below us: green hills, tiny farms, sheep dotted about like scattered rice, and a dark lake glittering beneath the crags. I knelt beside the wall and laid my palm against a stone. It was cold and rough, and it had been cut, shaped and hauled into place by somebody almost two thousand years ago, an effort that I found quite impossible to picture.",
"Kwesi had at last stopped complaining, and he was standing a little way off, hands buried in his pockets, gazing north across the desolate, empty land, apparently with nothing whatsoever to say.",
"“What would it have been like,” he asked at last, “to stand here and look at that, every day?”",
"I could not answer. I thought of all the soldiers who must have stood on this ridge, far from home, watching for something that might never come, and of the wind, which surely blew as hard for them as it did for us.",
"By the time we turned back, my feet ached and my hair was plastered flat with drizzle. But when I glanced behind me, the wall lay across the hills like a grey thread, stitched through the landscape by careful hands, and it seemed to me that it was no longer only a wall.",
], [
 dict(d="2b",k="short",m=1,q="Look at paragraph 1. Where did the writer and Kwesi begin their walk?",a="Housesteads Roman Fort.",g="Accept: Housesteads."),
 dict(d="2b",k="short",m=1,q="According to paragraph 1, in which year did the building of the wall begin?",a="AD 122.",g="Accept 122 / AD 122."),
 dict(d="2a",k="mc",m=1,q="In paragraph 4, what does the word “freckled” suggest about the stones?",opts=["They were perfectly smooth.","They were dotted with small patches of colour.","They were brand new.","They were covered in snow."],a="B"),
 dict(d="2g",k="short",m=2,q="The wall is described as “the spine of some enormous sleeping animal”. What impression does this give of the wall? Explain.",a="It is long and huge and rises and falls like a creature’s back; it seems alive but still and powerful.",g="1 mark for size / length / shape. 1 mark for explaining the effect of a sleeping animal (still, calm, alive, powerful)."),
 dict(d="2d",k="short",m=1,q="Why does the writer think the builders chose the line of the crags?",a="An enemy would have had to climb the cliff in full view.",g="Accept any answer about the cliff making approach hard / easily seen."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the text.",items=["The mist cleared and the view opened out.","They reached a milecastle.","They set out from the fort.","They turned back with aching feet."],a=[3,2,1,4],g=Q2),
 dict(d="2d",k="short",m=2,q="How can you tell that Kwesi’s attitude changed during the walk? Give two pieces of evidence.",a="He began to count his own steps; he stopped complaining and gazed north; he asked what it would have been like to stand there.",g="1 mark for each of two pieces of evidence. Max 2."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each statement.",items=["The wall is about seventy-three miles long.","The word “mile” comes from the Latin for a thousand paces.","The wall was built by Kwesi’s ancestors.","The writer touched one of the stones."],a=["T","T","F","T"],g=TF),
 dict(d="2g",k="short",m=1,q="The sheep are “dotted about like scattered rice”. What does this comparison help the reader to picture?",a="Small white shapes spread widely over the hills.",g="Accept any answer about small, pale and scattered."),
 dict(d="2a",k="mc",m=1,q="In paragraph 6, the wind had “scoured” the mist away. What does “scoured” suggest?",opts=["Cleared it away forcefully","Painted it","Invited it","Buried it quietly"],a="A"),
 dict(d="2d",k="short",m=2,q="Look at the final paragraph. “It seemed to me that it was no longer only a wall.” What does the writer now think the wall is? Use evidence to explain.",a="A work of people and a link to the past, because it was “stitched by careful hands” and the writer has pictured soldiers standing there.",g="1 mark for the idea that it stands for people / history / effort. 1 mark for evidence (soldiers on the ridge, stones hauled, stitched by careful hands)."),
 dict(d="2c",k="mc",m=1,q="What is the main purpose of paragraphs 2 and 3?",opts=["To describe the weather","To show that Kwesi is doubtful and to set up what the writer discovers","To explain how the wall was built","To give directions"],a="B"),
 dict(d="2d",k="mc",m=1,q="Which word best describes the writer’s feelings by the end of the walk?",opts=["Bored","Cross","Frightened","Thoughtful"],a="D"),
 dict(d="2c",k="mc",m=1,q="Which of these best summarises the text?",opts=["A sibling argument about a guidebook","A history of the Roman Empire","A description of a fort","A walk along a Roman wall that changes a boy’s attitude and gives the writer a sense of the past"],a="D"),
])

T(33, "33-6", "After the Final Whistle", "Description", [
"An hour after the final whistle, the stadium had surrendered its roar. The crowds, who had poured through the turnstiles in noisy tributaries, had drained away into the darkening streets, and what remained was a vast concave silence, as though the whole structure were holding its breath. Floodlights still burned on their tall masts, but they had been dimmed to a tired amber, and the pitch beneath them glowed an almost unnatural green.",
"In the stands, the emptiness felt strangely full. Thousands of plastic seats climbed away in curving terraces, their bright colours drained to grey by the fading light, and each one seemed to hold the memory of somebody who had leapt from it. Scarves had been left draped over railings, a single glove lay abandoned on a step, and a trodden programme fluttered along the concrete like a wounded bird. Everywhere the air smelled of cold chips, wet grass and spilled tea.",
"Down on the touchline, a small band of workers moved patiently through the litter. They wore orange jackets that glowed in the gloom, and they pushed wide brooms in slow, steady sweeps, gathering a drift of wrappers, paper cups and confetti into heaps. Their voices carried oddly in the cavernous space, rising to the roof and returning a moment late, so that every casual remark seemed to be spoken twice.",
"Beneath the stands, the players’ tunnel yawned like the mouth of a cave. Its walls were lined with faded photographs, and a puddle of muddy water had gathered at the foot of the steps, marking the place where, only an hour earlier, two teams had waited shoulder to shoulder for the signal to run out into the light. Nobody stood there now, although somewhere within, a door creaked as it swung slowly shut on its hinges.",
"The pitch itself bore the marks of the evening. Long scuffs curved across the penalty area where boots had skidded, and in the centre circle the turf was churned to bare brown earth. A groundsman knelt with a small fork, pressing the torn divots back into place, one at a time, as gently as if he were tucking a child into bed. By morning, he explained, the damage would be barely visible.",
"Above the far goal, the great scoreboard still showed the result, its white letters blazing on black. Nobody had thought to switch it off. It seemed to shine for an audience that had already gone home, insisting on a moment that was over.",
"Then, one by one, the floodlights were extinguished. Darkness poured down from the rim of the roof, swallowing the seats, the touchline and finally the pitch. For a heartbeat the scoreboard glowed alone, and then it, too, went out. All that remained was the distant hum of the city beyond the walls, and the quiet ticking of cooling metal as the stadium settled down to wait for the next time it would be needed.",
], [
 dict(d="2b",k="short",m=1,q="What colour were the jackets worn by the workers?",a="Orange.",g="Accept orange only."),
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does the word “surrendered” suggest about the stadium’s roar?",opts=["It had grown louder.","It had been given up and had faded away.","It had been recorded.","It had been ignored."],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the phrase from paragraph 2 that describes the smell of the stadium as including something to eat.",a="cold chips",g="Accept “cold chips”."),
 dict(d="2g",k="short",m=2,q="In paragraph 1, the writer describes the crowds as pouring through the turnstiles “in noisy tributaries”. What does this comparison suggest about the crowds, and why is it effective?",a="The crowds moved like streams flowing into a river, in many streams together; it makes them seem like a natural flow of water.",g="1 mark for the idea of crowds flowing like streams or water. 1 mark for the effect (many separate groups joining together / movement / noise)."),
 dict(d="2d",k="short",m=1,q="A programme is said to flutter “like a wounded bird”. What does this suggest about the programme?",a="It looks damaged and helpless, moving weakly.",g="Accept: it looks broken / injured / weak / sad."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["The floodlights were switched off.","The workers swept up the litter.","The scoreboard went dark.","The crowds left the stadium."],a=[3,2,4,1],g=Q2),
 dict(d="2d",k="short",m=2,q="Why do you think the writer says the emptiness “felt strangely full”? Use evidence from paragraph 2.",a="The empty seats and left-behind items suggest the people who had been there, so the stadium still feels as if it holds their memories.",g="1 mark for the idea that traces of the crowd remain / memories. 1 mark for evidence (scarves, glove, programme, “memory of somebody who had leapt from it”)."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each statement.",items=["The floodlights were dimmed before they were switched off.","The groundsman repaired the pitch with a fork.","The workers were silent.","The scoreboard was switched off first."],a=["T","T","F","F"],g=TF),
 dict(d="2g",k="short",m=2,q="The groundsman presses the turf back “as gently as if he were tucking a child into bed”. What does this simile suggest about him, and how does it make the reader feel?",a="He is caring and gentle towards the pitch; it makes the reader feel warmth and see the pitch as something precious.",g="1 mark for gentle / caring / patient. 1 mark for the effect on the reader (warmth, tenderness, the pitch seen as precious or alive)."),
 dict(d="2a",k="mc",m=1,q="In paragraph 3, what does “cavernous” suggest about the stadium?",opts=["It was very old.","It was huge and hollow like a cave.","It was damp.","It was crowded."],a="B"),
 dict(d="2d",k="short",m=1,q="Why do the workers’ voices seem to be “spoken twice”?",a="The sound echoes around the huge, empty space and returns a moment late.",g="Accept: echo."),
 dict(d="2d",k="mc",m=1,q="Why does the writer say the scoreboard “seemed to shine for an audience that had already gone home”?",opts=["To suggest it was broken","To show that it still displayed a result nobody was left to see","To say that it was very bright","To explain how it was powered"],a="B"),
 dict(d="2c",k="mc",m=1,q="Which of these best describes how the mood of the passage changes?",opts=["From excitement, to calm, to a quiet settling into rest","From fear, to anger, to relief","From boredom, to surprise, to joy","From sadness, to panic, to laughter"],a="A"),
 dict(d="2e",k="short",m=1,q="Look at the final sentence. What does it suggest will happen to the stadium?",a="It will be busy and full again the next time it is used for a match.",g="Accept any answer that says it will be used / filled with people again."),
])
